// 'dataPolicy' — Политика в отношении обработки ПДн по ст. 18.1 152-ФЗ. Это
// публикуемый документ, его не «принимают» при регистрации: он НЕ входит в
// LEGAL_KEYS (набор для окна согласия), поэтому его добавление не поднимает
// повторное согласие у уже зарегистрированных.
//
// 'marketing' — согласие на рекламную рассылку. Тоже вне LEGAL_KEYS: оно
// необязательное и хранится отдельной строкой, см. JT_MARKETING_CONSENT_VERSION.
export type LegalDocKey = 'terms' | 'privacy' | 'consent' | 'dataPolicy' | 'marketing';

export type LegalDoc = {
  title: string;
  /** Дата редакции. Меняется вместе с текстом — иначе запись согласия лжёт. */
  version: string;
  /**
   * Дата последней правки, ради которой надо спрашивать согласие заново.
   *
   * Двух дат вместо одной не от любви к сложности. 18 августа в документах
   * поменялся один адрес: почта поддержки переехала с чужого сервиса на свой.
   * Редакцию за это поднять надо — текст-то изменился, и делать вид, что нет,
   * значит врать в записи о согласии. А вот выкатывать из-за смены адреса
   * блокирующее окно всем четыремстам двадцати — нет: часть людей просто
   * уйдёт, и ради чего.
   *
   * Поэтому `version` честно отвечает «когда текст менялся», а эта дата —
   * «когда менялось что-то, ради чего стоит спросить». Поднимайте её, когда
   * меняется суть: состав данных, цели, сроки, права человека, кому передаём.
   * Не поднимайте на опечатки, вёрстку и контакты.
   */
  consentVersion: string;
  sections: { heading?: string; body: string }[];
};

